const items = $input.all().map(i => i.json);
if (!items.length || items[0].error) {
  return [{ json: { ok: false, error: items[0] ? (items[0].error.message || JSON.stringify(items[0].error)) : 'no rows returned' } }];
}
const need = ['rank','send_order','send_day','tier','status','firm','contact','email','subject','body_html','contact_status','sent_date','thread_id'];
const headers = Object.keys(items[0]);
const missing = need.filter(h => !headers.includes(h));
const status = {};
for (const r of items) { const s = String(r.status || '').trim() || '(blank)'; status[s] = (status[s] || 0) + 1; }
const q = items.filter(r => String(r.status).trim() === 'QUEUED').sort((a,b) => Number(a.send_order) - Number(b.send_order));
const first12 = q.slice(0, 12).map(r => [r.send_order, r.rank, r.firm, r.contact, String(r.email||'').includes('@') ? 'email ok' : 'NO EMAIL', String(r.body_html||'').length].join(' | '));
const aroa = items.filter(r => String(r.firm).startsWith('Aroa')).map(r => ({ rank: r.rank, status: r.status, contact: r.contact, send_order: r.send_order }));
const sentAlready = items.filter(r => String(r.sent_date||'').trim()).length;
const badBody = q.filter(r => !String(r.body_html||'').includes('calendly.com/investors-sidanaventures/30min')).length;
const oldSubject = items.filter(r => String(r.subject||'').includes('curated Indian dealflow')).length;
const fund2026 = items.filter(r => String(r.body_html||'').includes('fund</b> in 2026')).length;
const rakesh = items.filter(r => String(r.body_html||'').includes('linkedin.com/in/rakeshsidana')).length;
const sentRows = items.filter(r => String(r.status).trim() === 'SENT').map(r => [r.send_order, r.firm, r.contact, r.sent_date, r.thread_id ? 'thread ok' : 'NO THREAD'].join(' | '));
const errRows = items.filter(r => String(r.status).trim() === 'SEND_ERROR').map(r => [r.firm, r.notes].join(' | '));
const r2 = items.find(r => String(r.rank) === '2') || {};
const raw_rank2 = {};
for (const [k, v] of Object.entries(r2)) { if (!['body_html','evidence_urls','portfolio_companies','positioning','sector_on_file','contact_bio','recent_deal','stage_on_file'].includes(k)) raw_rank2[JSON.stringify(k)] = v; }
return [{ json: { raw_rank2, sent_rows: sentRows, error_rows: errRows, ok: true, rows: items.length, header_count: headers.length, missing_headers: missing, status, sent_already: sentAlready, queued_missing_calendly: badBody, rows_with_old_subject: oldSubject, rows_with_2026_fund: fund2026, rows_with_rakesh_linkedin: rakesh, aroa, first12 } }];
